def strongPasswordChecker(password: str) -> int:
    n = len(password)

    # Check for missing types
    has_lower = any('a' <= c <= 'z' for c in password)
    has_upper = any('A' <= c <= 'Z' for c in password)
    has_digit = any(c.isdigit() for c in password)
    missing_types = 3 - (has_lower + has_upper + has_digit)

    # Find lengths of runs of 3 or more same character
    lens = []
    i = 0
    # Identify lengths of every repeated sequence
    while i < n:
        j = i
        while j < n and password[j] == password[i]:
            j += 1
        if j - i >= 3:
            lens.append(j - i)
        i = j

    if n < 6:
        # Short password case
        return max(missing_types, 6 - n)
    elif n <= 20:
        # Just do replacements for repeats and missing types
        replace = 0
        for l in lens:
            replace += l // 3
        return max(replace, missing_types)
    else:
        # Need deletions!
        to_delete = n - 20
        replace = sum(l // 3 for l in lens)
        del_left = to_delete

        # Runs with l % 3 == 0: one deletion saves one replacement
        for l in lens:
            if l % 3 == 0 and del_left >= 1:
                replace -= 1
                del_left -= 1
        # Runs with l % 3 == 1: two deletions save one replacement
        for l in lens:
            if l % 3 == 1 and del_left >= 2:
                replace -= 1
                del_left -= 2
        # Any other run: three deletions save one replacement
        replace = max(0, replace - del_left // 3)

        return to_delete + max(missing_types, replace)

